package com.example.wallet.service;
import org.springframework.boot.ApplicationArguments;import org.springframework.boot.ApplicationRunner;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Component;
@Component public class DemoSeeder implements ApplicationRunner {private final JdbcTemplate jdbc;@Value("${wallet.seed-demo:false}") boolean enabled;public DemoSeeder(JdbcTemplate jdbc){this.jdbc=jdbc;}public void run(ApplicationArguments args){if(!enabled)return;for(String[] s:new String[][]{{"System Cash-In","CASH_IN"},{"System Cash-Out","CASH_OUT"},{"Fee Revenue","FEE_REVENUE"}}){jdbc.update("INSERT INTO accounts(user_id,name,account_type,is_system,balance_paise) SELECT NULL,?,?,true,0 WHERE NOT EXISTS (SELECT 1 FROM accounts WHERE account_type=? AND is_system=true)",s[0],s[1],s[1]);}jdbc.update("INSERT INTO users(name,email,phone,kyc_status) VALUES('Asha Demo','asha@example.test','+910000000001','VERIFIED') ON CONFLICT(email) DO NOTHING");jdbc.update("INSERT INTO users(name,email,phone,kyc_status) VALUES('Rahul Demo','rahul@example.test','+910000000002','VERIFIED') ON CONFLICT(email) DO NOTHING");jdbc.update("INSERT INTO accounts(user_id,name,account_type,is_system,balance_paise) SELECT u.id,'Main Wallet','WALLET',false,0 FROM users u WHERE u.email='asha@example.test' AND NOT EXISTS(SELECT 1 FROM accounts a WHERE a.user_id=u.id)");jdbc.update("INSERT INTO accounts(user_id,name,account_type,is_system,balance_paise) SELECT u.id,'Main Wallet','WALLET',false,0 FROM users u WHERE u.email='rahul@example.test' AND NOT EXISTS(SELECT 1 FROM accounts a WHERE a.user_id=u.id)");}}
